import{_ as s,o as e,c as i,ai as n}from"./chunks/framework.XEs52zTF.js";const k=JSON.parse('{"title":"优化必须保持语义","description":"","frontmatter":{"title":"优化必须保持语义","chapterId":"chapter16","prev":{"text":"进入 SSA 世界","link":"/chapter15"},"next":{"text":"走向本机代码","link":"/chapter17"}},"headers":[],"relativePath":"chapter16.md","filePath":"chapter16.md"}'),p={name:"chapter16.md"};function t(l,a,r,h,d,o){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="_16-优化-首先证明程序行为没有改变" tabindex="-1">16 优化：首先证明程序行为没有改变 <a class="header-anchor" href="#_16-优化-首先证明程序行为没有改变" aria-label="Permalink to &quot;16 优化：首先证明程序行为没有改变&quot;">​</a></h1><h2 id="学习目标与实验边界" tabindex="-1">学习目标与实验边界 <a class="header-anchor" href="#学习目标与实验边界" aria-label="Permalink to &quot;学习目标与实验边界&quot;">​</a></h2><p>本章是扩展实验，现有主线编译器没有对外承诺完整优化流水线。前置是 CFG、数据流和 SSA。你将学会常量折叠、传播、死代码消除、公共子表达式、循环优化，并知道哪些看似显然的变换在检查型整数与短路语义下并不成立。</p><p>优化的目标可以是运行更快、代码更小或编译更快，三者并不总一致。先建立正确性契约和可重复的测量，再讨论某个 pass 是否“更高级”。优化器不是一堆字符串替换规则，而是在前提成立时进行的语义保持变换。</p><h2 id="常量折叠与常量传播" tabindex="-1">常量折叠与常量传播 <a class="header-anchor" href="#常量折叠与常量传播" aria-label="Permalink to &quot;常量折叠与常量传播&quot;">​</a></h2><p>折叠把 <code>3+4</code> 变成 7；传播根据已知定义，把后续 x 替换成它的常量值。两者配合，<code>x=3; y=x+4</code> 能得到 <code>y=7</code>。SSA 中只需沿唯一定义追踪，但有 φ 时还要合并路径信息。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原 IR                     变换后</span></span>
<span class="line"><span>x0 = 3                    x0 = 3</span></span>
<span class="line"><span>y0 = add x0, 4            y0 = 7</span></span>
<span class="line"><span>print y0                  print 7</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>常量求值必须调用与运行时一致的算术规则。若 <code>2147483647+1</code> 原来应该报溢出，就不能在编译器宿主中使用 int32 算完再得到任意值。对 Sprout 现有的运行时错误契约，安全做法是保留这次运算，或在原来会执行的位置生成显式 trap；不能悄悄改成回绕，也不能把错误无条件提前到编译阶段。尤其 <code>false &amp;&amp; (2147483647+1==0)</code> 的右边不会执行，不能因扫描到常量溢出就拒绝它。如果另行设计“某些常量错误在编译期必须诊断”的语言规则，需要先改规范，再讨论这种额外诊断策略。</p><h2 id="合并分支时的信息格" tabindex="-1">合并分支时的信息格 <a class="header-anchor" href="#合并分支时的信息格" aria-label="Permalink to &quot;合并分支时的信息格&quot;">​</a></h2><p>对每个值记录三种状态：尚未获得信息、已知常量 c、不是单一常量。两个相同常量合并仍是该常量；不同常量合并则不是常量。循环需要迭代，不能第一次看到 φ 的一个输入就永久决定结果。</p><p>稀疏条件常量传播还追踪边是否可执行。若条件被证明为 true，就只让对应边进入分析，另一条不可执行路径中的不同常量不应污染结果。注意“尚未证明可执行”和“永远不可执行”不是一开始就能等同的结论，算法需要单调地更新信息。</p><h2 id="死代码消除的核心是可观察行为" tabindex="-1">死代码消除的核心是可观察行为 <a class="header-anchor" href="#死代码消除的核心是可观察行为" aria-label="Permalink to &quot;死代码消除的核心是可观察行为&quot;">​</a></h2><p>若 t 的结果无人使用，<code>t=copy 3</code> 通常可以删除；<code>t=call f()</code> 却不能仅因 t 不使用就删除，因为 f 可能打印、报错或不终止。Sprout 算术会检查溢出与除零，所以 <code>t=1/0</code> 的结果即使不用，也有可观察错误，不能当成纯粹无效计算直接删掉。</p><div class="language-sprout vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sprout</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> unused </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> /</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这段程序不能被优化成只打印 7。可在 IR 中明确区分纯且不会失败的运算、可能 trap 的检查运算、具有副作用的调用。分析若能证明除数非零且不会溢出，才有机会把某次检查运算当作可删除的纯计算。</p><p>一个简单 DCE 保留现有控制流，把所有终结指令（包括条件分支）、print、可能失败和有副作用的指令作为根，反向标记其数据依赖，再删除未标记的纯指令。分支条件也是终结指令的操作数，不能因为它不参与最后的数字结果就删除。更激进地删除控制流还需要控制依赖、终止行为等额外分析，不属于这个入门版本。只做“引用计数为零就删”时还要考虑循环依赖和 φ，标记清扫更容易解释。</p><h2 id="公共子表达式与内存别名" tabindex="-1">公共子表达式与内存别名 <a class="header-anchor" href="#公共子表达式与内存别名" aria-label="Permalink to &quot;公共子表达式与内存别名&quot;">​</a></h2><p>若 a、b 的值没变，而且前一次运算的定义支配后一次使用，重复 <code>add a,b</code> 可以复用已有结果。这里复用的是当前路径上已经算出的值，不能凭空把可能报错的运算提前到原来不执行它的路径。SSA 名字使输入是否相同容易判断：相同操作码、类型、输入值和相关语义标志，可以形成一个键，但“键相同”不代替支配检查。两个互斥分支里的同形表达式，不能直接让右分支使用只在左分支定义的临时值。交换律允许 add 的输入规范化，但 sub 不允许。</p><p>内存读不能简单照搬这条规则：<code>x=load p; store q,1; y=load p</code> 中，若 p、q 可能指向同一位置，第二次 load 可能不同。源语言尚无指针时可以暂不处理；一旦增加数组与引用，就需要别名分析、内存效果或 MemorySSA 等模型。写“所有相同文字的表达式都合并”会产生错误代码。</p><h2 id="循环优化为什么需要更多证明" tabindex="-1">循环优化为什么需要更多证明 <a class="header-anchor" href="#循环优化为什么需要更多证明" aria-label="Permalink to &quot;循环优化为什么需要更多证明&quot;">​</a></h2><p>循环不变代码外提尝试把每轮都相同的计算放到循环前。但 <code>while (false) { x=1/0; }</code> 原来不除零，外提就改变行为。即使表达式输入在循环中不变，也要证明提前执行不会新增错误、内存访问或副作用。</p><p>归纳变量与强度削弱可把某些重复乘法变成增量，但检查型整数可能使中间溢出的时机改变。循环展开会增加代码体积；向量化还需证明各次迭代不存在破坏性的依赖。资料库中循环归纳表达式、程序依赖图与多面体相关书目，适合在这些基本证明习惯建立后继续读。</p><h2 id="实验-一条规则配一个反例" tabindex="-1">实验：一条规则配一个反例 <a class="header-anchor" href="#实验-一条规则配一个反例" aria-label="Permalink to &quot;实验：一条规则配一个反例&quot;">​</a></h2><p>在纸上为每条变换写“输入模式—前提—输出—反例”。例如 <code>x+0→x</code> 对合法 int32 x 成立；<code>0*x→0</code> 只有在求 x 的过程没有必须保留的行为时才能删去 x 的求值；<code>(x+1)-1→x</code> 在检查型整数下会改变 x 为最大值时的溢出行为。</p><p>为一个手工三地址函数实现仅处理安全常量的折叠。每次变换后运行第 13 章验证器，输出变换前后 dump，再用小解释器枚举小范围输入比较结果、错误类别与打印序列。不要只比较最终返回数字。</p><h2 id="常见错误、练习与验收" tabindex="-1">常见错误、练习与验收 <a class="header-anchor" href="#常见错误、练习与验收" aria-label="Permalink to &quot;常见错误、练习与验收&quot;">​</a></h2><p>练习一：<code>false &amp;&amp; dangerous()</code> 能否直接折叠？练习二：<code>x/x→1</code> 需要哪些前提？练习三：为什么在可达性清理后重新做 DCE 可能删除更多指令？</p><details><summary>参考答案</summary><p>第一题可以把整个表达式折为 false，因为右侧按短路规则原本就不执行；不能因此顺便删除左侧本来必需的副作用。第二题至少要证明 x 非零并保留 x 原有求值行为；值已命名与表达式还未求值是不同场景。第三题不可达块删除后，某些值失去最后一个使用者，新的死值会暴露。验收需要正常、错误、短路与零次循环四类用例，并在每个 pass 后验证 IR。</p></details><h2 id="来源与后续" tabindex="-1">来源与后续 <a class="header-anchor" href="#来源与后续" aria-label="Permalink to &quot;来源与后续&quot;">​</a></h2><p>本地 SSA 论文第 2—3 页包含常量传播的动机；<code>compilers-papers-we-love/optimization/</code> 下程序依赖图与 SSA 论文提供继续阅读路径。<a href="https://llvm.org/docs/CommandGuide/opt.html" target="_blank" rel="noreferrer">LLVM opt 文档</a> 说明如何运行和检查实际优化流程。下一章进入指令选择与寄存器分配，始终保留这里的语义契约。</p>`,30)])])}const u=s(p,[["render",t]]);export{k as __pageData,u as default};
